import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { toast } from 'sonner';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import App from './app';
import type {
  ChangeDetail,
  ChangeList,
  ModelInfo,
  RecordEnvelope,
  WorkspaceRecord,
