    mockIpc();
  });

  afterEach(() => {
    vi.unstubAllEnvs();
  });

  it('壳态点击 nav-info：hash 落 #/info、基础信息页呈现（info-summary 在场）、变更页内容卸载、nav-info 激活', async () => {
